    from collections import defaultdict
    h, w = len(grid), len(grid[0])
    seen=set(); count=defaultdict(int)
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=2 or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); cells=[]
            while stack:
                x,y=stack.pop(); cells.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            if len(cells)!=4: continue
            rs={x for x,y in cells}; cs={y for x,y in cells}
            if len(rs)==2 and len(cs)==3:
                bar=max(rs,key=lambda x:sum(a==x for a,b in cells))
                stem=next(x for x in rs if x!=bar)
                count['up' if stem<bar else 'down']+=1
            elif len(rs)==3 and len(cs)==2:
                bar=max(cs,key=lambda y:sum(b==y for a,b in cells))
                stem=next(y for y in cs if y!=bar)
