    # Reconstruct the shape's target raster from the components and their
    # stem direction, then crop the empty border to a compact 3x6 code.
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 2 or (r,c) in seen: continue
            todo=[(r,c)]; seen.add((r,c)); comp=[]
            while todo:
                x,y=todo.pop(); comp.append((x,y))
                for dx,dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=x+dx,y+dy
                    if 0<=a<h and 0<=b<w and grid[a][b]==2 and (a,b) not in seen:
                        seen.add((a,b)); todo.append((a,b))
            if len(comp)==4:
                objects.append(comp)
    counts=[0,0,0,0]
    for comp in objects:
        rs={x for x,y in comp}; cs={y for x,y in comp}
        if len(rs)==2 and len(cs)==3:
            bar=max(rs,key=lambda rr:sum(x==rr for x,y in comp))
            stem=next(rr for rr in rs if rr!=bar)
            counts[0 if stem<bar else 1]+=1
        elif len(rs)==3 and len(cs)==2:
            bar=max(cs,key=lambda cc:sum(y==cc for x,y in comp))
            stem=next(cc for cc in cs if cc!=bar)
            counts[2 if stem<bar else 3]+=1
    out=[[0]*6 for _ in range(3)]
    # Directional symbol counts occupy their corresponding columns.
    for i,n in enumerate(counts):
        for j in range(min(n,3)):
            out[j][i*2 if i<3 else 5]=([3,3,1,1][i])
    return out
